1	// Package logfile persists event batches as an append-only sequence of
2	// length-prefixed, CRC-checked frames.
3	//
4	// Frame layout (all integers big-endian):
5	//
6	//	[4 bytes payload length][4 bytes CRC32-IEEE of payload][payload bytes]
7	//
8	// The payload is a JSON array encoded with events.MarshalBatch.
9	package logfile
10	
11	import (
12		"errors"
13		"fmt"
14		"os"
15		"path/filepath"
16	
17		"github.com/cocosolocoder/signalroom/internal/events"
18	)
19	
20	const (
21		logName  = "events.log"
22		lockName = "lock"
23	)
