143	func (p *serverProc) waitExit(t *testing.T, wantCode int) {
144		t.Helper()
145		select {
146		case err := <-p.waitCh:
147			_ = err // captured below via ProcessState
148		case <-time.After(5 * time.Second):
149			t.Fatalf("process did not exit; output:\n%s", p.logs.String())
150		}
151		state := p.cmd.ProcessState
152		if state == nil {
153			t.Fatal("process state unavailable after wait")
154		}
155		got := state.ExitCode()
156		if got != wantCode {
157			t.Fatalf("want exit %d, got %d; output:\n%s", wantCode, got, p.logs.String())
158		}
159	}
