220	func waitTCPPortClosed(t *testing.T, addr string) {
221		t.Helper()
222		deadline := time.Now().Add(5 * time.Second)
223		for time.Now().Before(deadline) {
224			conn, err := net.DialTimeout("tcp", addr, 100*time.Millisecond)
225			if err != nil {
226				return
227			}
228			conn.Close()
229			time.Sleep(2 * time.Millisecond)
230		}
231		t.Fatalf("port %s still accepting connections", addr)
232	}
