443	func TestServeFailsOnMidCorruptionWithoutMutation(t *testing.T) {
444		dataDir := t.TempDir()
445		first := startServer(t, dataDir)
446		postEvents(t, first, `{"events":[{"id":"good","service":"svc","severity":"info","message":"m","at":"2026-10-01T09:00:00Z"}]}`)
447		first.signal(t, syscall.SIGKILL)
448		first.waitExit(t, -1)
449		waitTCPPortClosed(t, first.addr)
450	
451		path := filepath.Join(dataDir, "events.log")
452		original, err := os.ReadFile(path)
453		if err != nil {
454			t.Fatal(err)
455		}
456		firstLen := 8 + int(binary.BigEndian.Uint32(original[0:4]))
457	
458		payload := []byte(`[{"id":"bad","service":"svc","severity":"info","message":"m","at":"2026-10-01T09:01:00Z"}]`)
459		bad := make([]byte, 8+len(payload))
460		binary.BigEndian.PutUint32(bad[0:4], uint32(len(payload)))
461		binary.BigEndian.PutUint32(bad[4:8], crc32.ChecksumIEEE(payload))
462		copy(bad[8:], payload)
463		bad[8] ^= 0xFF // checksum mismatch in a complete middle frame
464		corrupt := append(original[:firstLen], bad...)
465		if err := os.WriteFile(path, corrupt, 0o644); err != nil {
466			t.Fatal(err)
467		}
468	
469		logs := &safeBuffer{}
470		failing := exec.Command(binaryPath, "serve", "--addr", "127.0.0.1:0", "--data", dataDir)
471		failing.Stdout = logs
472		failing.Stderr = logs
473		if err := failing.Start(); err != nil {
474			t.Fatal(err)
475		}
476		done := make(chan error, 1)
477		go func() { done <- failing.Wait() }()
478		ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
479		defer cancel()
480		select {
481		case err := <-done:
482			if err == nil {
483				t.Fatal("corrupt log must prevent startup")
484			}
485			if ee, ok := err.(*exec.ExitError); !ok || ee.ExitCode() == 0 {
486				t.Fatalf("corrupt log must exit non-zero: %v", err)
487			}
488		case <-ctx.Done():
489			failing.Process.Kill()
490			t.Fatal("server stayed up despite corrupt log")
491		}
492	
493		after, err := os.ReadFile(path)
494		if err != nil {
495			t.Fatal(err)
496		}
497		if !bytes.Equal(after, corrupt) {
498			t.Fatal("failed startup must not modify the corrupt data")
499		}
500	}
