607	func TestServePageWorksOnLegacyDataDir(t *testing.T) {
608		// A data directory written by an older version has events.log but no
609		// cursor.key or snapshots/. The new server must generate the key and
610		// page through the recovered events.
611		dataDir := t.TempDir()
