644		dataDir := t.TempDir()
645		p := startServer(t, dataDir)
646		postEvents(t, p, `{"events":[
647			{"id":"e1","service":"gateway","severity":"critical","message":"m","at":"2026-10-01T10:00:05Z","labels":{"env":"prod"}},
648			{"id":"e2","service":"gateway","severity":"critical","message":"m","at":"2026-10-01T10:01:05Z","labels":{"env":"prod"}},
